"""라오어 무한매수법 — 종목 하나의 하루치 규칙 (순수 함수, 부수효과 없음).

백테스트와 드라이런이 같은 step()을 호출하므로 검증한 규칙 = 돌리는 규칙이다.

[일반 모드] (책 규칙, 사용자 제공 원문)
  - 원금을 40분할. 1회분 = 현재 잔금 ÷ (40 − T)  (처음엔 원금/40, 리버스 복귀 후엔 카페 규칙대로 재계산)
  - 첫 매수: 장중 아무 때 1주 (여기서는 시가).
  - 이후 매일 1회분 LOC: 절반 '평단 LOC'(종가 ≤ 평단일 때만), 절반 '큰수 LOC'(항상 체결).
    하루 1회분을 넘기지 않는다. 정수 주식만.
  - 매일 보유 전량을 평단 +target 지정가로 매도 대기 → 체결 = 사이클 종료.
  - 매도된 날은 큰수 LOC만 체결 → 그 수량으로 새 사이클 (규칙 1-6).
[회차 T] 금액 기준 (2026-09-30 사용자 확인, 엑셀 v2.2·카페 자료와 동일):
  일반 매수 체결 시 T += 체결금액 ÷ 1회분. 1주 단위 매수라 0.5회차 주문이 0.31처럼 들어갈 수 있다.
  남은 돈은 원금 안에 남아 다음 매수에 쓰이므로 40개 몫은 결국 다 쓰인다 (걸리는 날짜만 늘어남).
[리버스 모드] (카페 자료, 2026-09-30 사용자 지시로 적용)
  - 진입: T > 39 AND 잔금으로 1주도 못 삼 → 그날이 리버스 1일차.
  - 1일차: 매수 없음, 보유 floor(수량/20) 을 종가(MOC)에 매도. T ×= 0.95.
  - 2일차~: ★ = 직전 5거래일 종가 평균 (당일 종가 미포함).
      매도 LOC ★+1센트 floor(현재수량/20) → 체결 시 T ×= 0.95
      매수 LOC ★−1센트 (현재 잔금 ÷ 4) 정수주 → 체결 시 T += (40 − T) × 0.25
      LOC 둘 다 종가로 판정하므로 같은 날 둘 다 체결되는 일은 없다 (★ 동일가 = 둘 다 미체결).
  - 종료: 종가 > 평단 × (1 − 종료기준) → 다음 거래일부터 일반 모드. T·잔금·보유 그대로.
    종료기준은 종목별 사용자 파라미터 (TQQQ 15%, SOXL 20% — 그 외 종목은 자료에 없어 필수 입력).
  - 외부 자금 투입 없음: 리버스 매도대금·잔금 안에서만.
[사이클 자금] 사이클 종료 시 잔금이 원금보다 많으면 초과분은 따로 두고(재투입 안 함),
  적으면 줄어든 금액으로 다음 사이클을 한다 (외부 자금 투입 금지).
"""

import math
from dataclasses import dataclass, replace

from strategy.base import Bar

NORMAL, REVERSE_DAY1, REVERSE = "NORMAL", "REVERSE_DAY1", "REVERSE"
STAR_DAYS = 5


@dataclass(frozen=True)
class Params:
    principal: float = 10_000.0     # 이 종목 전용 원금 (USD)
    splits: int = 40
    target: float = 0.10            # 평단 대비 매도 목표 (0.10 = +10%)
    fee_rate: float = 0.001         # 매수/매도 각각
    reverse_exit: float | None = None   # 리버스 종료기준 (0.15 = 평단 −15% 위 종가). None이면 리버스 종료 불가
    version: str = "book"           # "book" = 책 규칙 + 카페 리버스 / "v22" = V2.2 (★%·전후반전·쿼터손절)
    interval: int = 1               # 매수 주기(거래일). 1 = 매일. N>1 이면 N거래일마다 한 번만 LOC·MOC 판단 (v22 전용, 익절 지정가는 매일)

    @property
    def unit(self) -> float:
        """처음 1회분 (원금/40) — 화면·검사용. 실제 매수는 Position.unit(p)을 쓴다."""
        return self.principal / self.splits

    @property
    def reverse_div(self) -> int:
        return self.splits // 2         # 40분할 → 20, 20분할 → 10

    @property
    def reverse_mult(self) -> float:
        return 1 - 2 / self.splits      # 40분할 → 0.95, 20분할 → 0.90


@dataclass(frozen=True)
class Position:
    qty: int = 0
    cost: float = 0.0               # 보유분 매수원가 (수수료 제외) → 평단 = cost/qty
    fees: float = 0.0               # 보유분 매수수수료
    start: str = ""                 # 이번 사이클 시작일
    days: int = 0                   # 이번 사이클 경과 거래일
    t: float = 0.0                  # 회차 T (금액 기준, 리버스 공식으로도 변함). 소수점 그대로 유지
    cash: float = 0.0               # 이 종목 사이클 잔금
    cap: float = 0.0                # 이번 사이클 시작 자금 (사이클 손익 = 끝난 뒤 잔금 − cap)
    mode: str = NORMAL
    closes: tuple = ()              # 직전 거래일 종가들 (★ 계산용, 최근 5개)
    qbuys: int = 0                  # (V2.2) 쿼터손절 중 체결된 매수 횟수
    qunit: float = 0.0              # (V2.2) 쿼터손절 1회분

    @property
    def avg(self) -> float:
        return self.cost / self.qty if self.qty else 0.0

    @property
    def spent(self) -> float:
        return self.cost + self.fees

    def unit(self, p: Params) -> float:
        """1회분 = 잔금 ÷ (분할수 − T). T가 분할수에 닿으면 0."""
        room = p.splits - self.t
        return self.cash / room if room > 1e-9 else 0.0

    def star(self) -> float | None:
        return sum(self.closes[-STAR_DAYS:]) / STAR_DAYS if len(self.closes) >= STAR_DAYS else None


def fresh(p: Params, capital: float | None = None) -> Position:
    """새 사이클 시작 상태 (자금 = capital, 없으면 원금)."""
    c = p.principal if capital is None else capital
    return Position(cash=c, cap=c)


@dataclass(frozen=True)
class Fill:
    date: str
    side: str                       # BUY | SELL
    kind: str                       # first | avg | big | sell(익절 전량) | rsell(리버스 매도) | qbuy(쿼터매수)
    qty: int
    price: float


@dataclass(frozen=True)
class Cycle:
    start: str
    end: str
    days: int
    invested: float                 # 사이클 시작 자금
    profit: float                   # 순손익 (수수료·리버스 손실 포함) = 끝난 뒤 잔금 − 시작 자금
    principal: float
    open: bool = False              # True = 아직 안 끝난 사이클을 평가가로 계산한 것

    @property
    def pnl_rate(self) -> float:
        """원금 대비 수익률 — 몬테카를로가 읽는 필드."""
        return self.profit / self.principal


@dataclass(frozen=True)
class DayResult:
    position: Position
    fills: tuple[Fill, ...] = ()
    cycle: Cycle | None = None
    exhausted: bool = False         # 리버스 진입 또는 1주도 못 사는 상태
    skipped: str = ""               # 비어 있지 않으면 그날은 매매하지 않음 (사유)
    event: str = ""                 # reverse_enter | reverse_exit | ""
    set_aside: float = 0.0          # 사이클 종료 시 원금 초과분 (재투입 안 하고 따로 둔 이익)


def buy_split(unit: float, price: float) -> tuple[int, int]:
    """1회분 수량을 (평단 LOC, 큰수 LOC)로 나눈다. 홀수면 남는 1주는 평단 LOC 몫."""
    total = math.floor(unit / price) if price > 0 and unit > 0 else 0
    big = total // 2
    return total - big, big


def sell_price(pos: Position, p: Params) -> float | None:
    return pos.avg * (1 + p.target) if pos.qty else None


def floor_cent(x: float) -> float:
    return math.floor(round(x * 100, 6)) / 100


def ceil_cent(x: float) -> float:
    return math.ceil(round(x * 100, 6)) / 100


def reverse_prices(pos: Position) -> tuple[float, float] | None:
    """(매도 LOC 가격 ★+1센트, 매수 LOC 가격 ★−1센트). ★ 계산 불가면 None."""
    s = pos.star()
    if s is None:
        return None
    sell_px = round(floor_cent(s) + 0.01, 2)            # ★보다 확실히 위 첫 센트
    buy_px = round(ceil_cent(s) - 0.01, 2)              # ★보다 확실히 아래 첫 센트
    return sell_px, buy_px


def reverse_exit_price(pos: Position, p: Params) -> float | None:
    return pos.avg * (1 - p.reverse_exit) if pos.qty and p.reverse_exit is not None else None


def should_enter_reverse(pos: Position, p: Params, price: float) -> bool:
    """T > 분할수−1 AND 잔금으로 1주도 못 삼 (카페 1-2: T만으로 진입 금지)."""
    return (pos.mode == NORMAL and pos.qty > 0 and pos.t > p.splits - 1
            and pos.cash < price * (1 + p.fee_rate))


def _bad_bar(b: Bar) -> str:
    if b.close <= 0 or b.open <= 0:
        return "가격 0"
    if b.volume <= 0:
        return "거래량 0 (거래정지/휴장 의심)"
    if not (b.low <= min(b.open, b.close) and b.high >= max(b.open, b.close)):
        return "시고저종 불일치"
    return ""


def apply_buy(pos: Position, qty: int, price: float, p: Params, date: str, t_add: float) -> Position:
    amount = qty * price
    fee = amount * p.fee_rate
    return replace(pos, qty=pos.qty + qty, cost=pos.cost + amount, fees=pos.fees + fee,
                   cash=pos.cash - amount - fee, start=pos.start or date, t=pos.t + t_add)


def apply_sell(pos: Position, qty: int, price: float, p: Params, t_mult: float = 1.0) -> Position:
    """부분 매도: 원가·수수료는 수량 비례로 줄이고 평단은 유지."""
    part = qty / pos.qty
    return replace(pos, qty=pos.qty - qty, cost=pos.cost * (1 - part), fees=pos.fees * (1 - part),
                   cash=pos.cash + qty * price * (1 - p.fee_rate), t=pos.t * t_mult)


def affordable(cash: float, want: int, price: float, p: Params) -> int:
    return max(0, min(want, math.floor(max(0.0, cash) / (price * (1 + p.fee_rate)))))


def normal_t_add(amount: float, unit: float) -> float:
    return amount / unit if unit > 0 else 0.0


def close_cycle(pos: Position, p: Params, date: str) -> tuple[Position, Cycle, float]:
    """전량 익절 뒤: 사이클 손익 확정, 원금 초과분은 따로 두고 다음 사이클 자금을 정한다."""
    cyc = Cycle(start=pos.start, end=date, days=pos.days + 1, invested=pos.cap,
                profit=pos.cash - pos.cap, principal=p.principal)
    next_cap = min(p.principal, pos.cash)
    return replace(fresh(p, next_cap), closes=pos.closes), cyc, pos.cash - next_cap


def _with_close(pos: Position, close: float) -> Position:
    return replace(pos, closes=(pos.closes + (close,))[-STAR_DAYS:])


def step(pos: Position, b: Bar, p: Params) -> DayResult:
    """하루(일봉 하나)를 규칙대로 진행한다. 입력 pos는 변경하지 않는다."""
    bad = _bad_bar(b)
    if bad:
        return DayResult(position=pos, skipped=bad)
    if p.version == "v22":
        from . import v22
        prev = pos.closes[-1] if pos.closes else None
        r = v22.step(pos, b, p, prev)
        return replace(r, position=_with_close(r.position, b.close))
    if pos.cap == 0 and pos.qty == 0:                   # 처음 시작 — 원금으로 자금 설정
        pos = replace(fresh(p), closes=pos.closes)
    if pos.mode == REVERSE_DAY1:
        return _reverse_day1(pos, b, p)
    if pos.mode == REVERSE:
        return _reverse_day(pos, b, p)
    return _normal_day(pos, b, p)


def _normal_day(pos: Position, b: Bar, p: Params) -> DayResult:
    if pos.qty == 0:                                    # 첫 매수: 1주 @ 시가 (책 1-4(1))
        if affordable(pos.cash, 1, b.open, p) < 1:
            return DayResult(position=_with_close(pos, b.close), exhausted=True)
        unit = pos.unit(p)
        new = replace(apply_buy(pos, 1, b.open, p, b.date, normal_t_add(b.open, unit)), days=1)
        return DayResult(position=_with_close(new, b.close),
                         fills=(Fill(b.date, "BUY", "first", 1, b.open),))

    fills: list[Fill] = []
    cycle, set_aside = None, 0.0
    old_avg = pos.avg
    target = sell_price(pos, p)
    sold = b.high >= target
    if sold:
        px = max(target, b.open)                        # 갭상승이면 시가에 체결
        fills.append(Fill(b.date, "SELL", "sell", pos.qty, px))
        pos, cycle, set_aside = close_cycle(apply_sell(pos, pos.qty, px, p), p, b.date)
    else:
        pos = replace(pos, days=pos.days + 1)
        ref = pos.closes[-1] if pos.closes else b.open  # 주문 시점에 아는 가격
        if should_enter_reverse(pos, p, ref):           # 소진 → 오늘이 리버스 1일차
            return _reverse_day1(replace(pos, mode=REVERSE_DAY1), b, p, entered=True)

    unit = pos.unit(p)
    n_avg, n_big = buy_split(unit, b.close)
    q = affordable(pos.cash, n_big, b.close, p)
    if q:
        pos = apply_buy(pos, q, b.close, p, b.date, normal_t_add(q * b.close, unit))
        fills.append(Fill(b.date, "BUY", "big", q, b.close))
    if not sold and b.close <= old_avg:
        q = affordable(pos.cash, n_avg, b.close, p)
        if q:
            pos = apply_buy(pos, q, b.close, p, b.date, normal_t_add(q * b.close, unit))
            fills.append(Fill(b.date, "BUY", "avg", q, b.close))
    if sold and pos.qty:
        pos = replace(pos, start=b.date, days=1)

    exhausted = pos.qty > 0 and not fills and affordable(pos.cash, 1, b.close, p) < 1
    return DayResult(position=_with_close(pos, b.close), fills=tuple(fills), cycle=cycle,
                     exhausted=exhausted, set_aside=set_aside)


def _exit_check(pos: Position, b: Bar, p: Params) -> tuple[Position, str]:
    px = reverse_exit_price(pos, p)
    if px is not None and b.close > px:
        return replace(pos, mode=NORMAL), "reverse_exit"   # 다음 거래일부터 일반 모드
    return pos, ""


def _reverse_day1(pos: Position, b: Bar, p: Params, entered: bool = False) -> DayResult:
    """매수 없음. floor(수량/20) 종가(MOC) 강제 매도, T ×= 0.95. ★ 미사용."""
    fills = []
    q = pos.qty // p.reverse_div
    if q >= 1:
        pos = apply_sell(pos, q, b.close, p, t_mult=p.reverse_mult)
        fills.append(Fill(b.date, "SELL", "rsell", q, b.close))
    pos = replace(pos, mode=REVERSE, days=pos.days + (0 if entered else 1))
    pos, ev = _exit_check(pos, b, p)
    return DayResult(position=_with_close(pos, b.close), fills=tuple(fills), exhausted=True,
                     event=ev or ("reverse_enter" if entered else ""))


def _reverse_day(pos: Position, b: Bar, p: Params) -> DayResult:
    pos = replace(pos, days=pos.days + 1)
    fills = []
    prices = reverse_prices(pos)
    if prices is not None:
        sell_px, buy_px = prices
        sq = pos.qty // p.reverse_div
        if b.close >= sell_px and sq >= 1:              # ★ 위 LOC 매도 체결
            pos = apply_sell(pos, sq, b.close, p, t_mult=p.reverse_mult)
            fills.append(Fill(b.date, "SELL", "rsell", sq, b.close))
        elif b.close <= buy_px:                         # ★ 아래 LOC 쿼터매수 체결
            bq = affordable(pos.cash / 4, 10**9, buy_px, p)   # 쿼터 = 현재 잔금의 1/4 (지정가 기준 정수주)
            if bq >= 1:
                pos = apply_buy(pos, bq, b.close, p, b.date, (p.splits - pos.t) * 0.25)
                fills.append(Fill(b.date, "BUY", "qbuy", bq, b.close))
    pos, ev = _exit_check(pos, b, p)
    return DayResult(position=_with_close(pos, b.close), fills=tuple(fills), exhausted=True, event=ev)


def merge_bars(bars: list, n: int) -> list:
    """일봉을 N거래일 봉으로 묶는다 (시가=첫날, 고가·저가=기간 최고·최저, 종가·날짜=마지막 날). 덜 찬 마지막 묶음은 버린다.
    매수 주기 N: LOC·MOC 는 묶음의 종가로 한 번 판단하고, 익절 지정가는 기간 내내 걸려 있으니 고가로 판정된다."""
    if n <= 1:
        return list(bars)
    out = []
    for i in range(0, len(bars) - n + 1, n):
        g = bars[i:i + n]
        out.append(Bar(date=g[-1].date, open=g[0].open, high=max(b.high for b in g), low=min(b.low for b in g),
                       close=g[-1].close, volume=sum(b.volume for b in g)))
    return out
